class RecordSource:
    def __init__(self, records: dict[str, str]) -> None:
        self._records = dict(records)

    def read(self, key: str) -> str | None:
        if not key:
            raise ValueError('empty key')
        return self._records.get(key)

class StrictSource(RecordSource):
    def read(self, key: str) -> str:
        result = super().read(key)
        if result is None:
            raise LookupError(key)
        return result

def read_title(source, key):
    title = source.read(key)
    return 'без названия' if title is None else title

